1	// build.js の図を、Google Slides API の batchUpdate の要求に変換する。
2	// build.js が呼ぶ pptxgenjs の代わりに、呼び出しを記録する偽物を読み込ませ、
3	// 記録した図形を要求に変換して、スライドの範囲ごとに JSON のファイルに書き出す。
4	//
5	// 実行: node gslides.js <出力ディレクトリ> <最初のスライド>-<最後のスライド> [--rgb] [--master <id>] [--delete <id>]
6	//   --rgb     テーマの色を参照せず、RGB の値で書く（マスターの配色を変えられないとき）
7	//   --master  マスターの objectId。指定すると、マスターの配色をこの資料のテーマに変える要求を先頭に入れる
8	//   --delete  消すスライドの objectId（Drive が作った最初のスライド）
9	// ノートは別に書き出す: node gslides.js <出力ディレクトリ> notes <ノートの ID の JSON>
10	const fs = require("fs");
11	const path = require("path");
12	const Module = require("module");
13	
14	const PT = 72; // 1 インチのポイント数
15	// Google スライドのテキストの内側の余白。API では変えられないので、余白 0 の文字の箱をこの分だけ広げる
16	const PAD_X = 0.1, PAD_Y = 0.05;
17	const FONT = "Noto Sans JP";
18	const BULLET_INDENT = 16; // 箇条書きの本文の字下げ（ポイント）
19	
20	const SHAPES = {
21	  ROUNDED_RECTANGLE: "ROUND_RECTANGLE", RECTANGLE: "RECTANGLE", OVAL: "ELLIPSE",
22	  PENTAGON: "HOME_PLATE", CHEVRON: "CHEVRON", CAN: "CAN", LINE: "LINE",
23	};
24	const OVERLAY = new Set(["ELLIPSE", "CAN", "CHEVRON", "HOME_PLATE"]);
25	const SCHEME = {
26	  text1: "@DARK1", text2: "@DARK2", background1: "@LIGHT1", background2: "@LIGHT2",
27	  accent1: "@ACCENT1", accent2: "@ACCENT2", accent3: "@ACCENT3",
28	  accent4: "@ACCENT4", accent5: "@ACCENT5", accent6: "@ACCENT6",
29	};
30	const THEME_KEYS = {
31	  DARK1: "dk1", LIGHT1: "lt1", DARK2: "dk2", LIGHT2: "lt2",
32	  ACCENT1: "accent1", ACCENT2: "accent2", ACCENT3: "accent3",
33	  ACCENT4: "accent4", ACCENT5: "accent5", ACCENT6: "accent6",
34	  HYPERLINK: "hlink", FOLLOWED_HYPERLINK: "folHlink",
35	};
36	
37	class FakeSlide {
38	  constructor(master) { this.master = master; this.items = []; this.notes = ""; }
39	  addText(t, o) { this.items.push({ kind: "text", t, o }); }
40	  addShape(type, o) { this.items.push({ kind: "shape", type, o }); }
41	  addNotes(t) { this.notes = t; }
42	}
43	class FakePptx {
44	  constructor() { this.slides = []; this.masters = {}; this.SchemeColor = SCHEME; this.shapes = SHAPES; }
45	  defineSlideMaster(m) { this.masters[m.title] = m; }
46	  addSection() {}
47	  addSlide({ masterName }) { const s = new FakeSlide(this.masters[masterName]); this.slides.push(s); return s; }
48	  async writeFile() {}
49	}
50	
51	let captured = null;
52	const origLoad = Module._load;
53	Module._load = function (request, parent, isMain) {
54	  if (request === "pptxgenjs") return function () { const p = new FakePptx(); captured = { pres: p }; return p; };
55	  if (request.endsWith("apply_theme.js")) return { applyTheme: async (_f, theme) => { captured.theme = theme; } };
56	  return origLoad.apply(this, arguments);
57	};
58	
59	// ---- 引数 ----
60	const [outDir, range, ...rest] = process.argv.slice(2);
61	const flag = (n) => rest.includes(n);
62	const opt = (n) => { const i = rest.indexOf(n); return i >= 0 ? rest[i + 1] : undefined; };
63	process.env.PPTX_SKILL_DIR = process.env.PPTX_SKILL_DIR || "/nonexistent";
64	process.argv = [process.argv[0], path.join(__dirname, "build.js"), "unused.pptx"];
65	require("./build.js");
66	
67	setImmediate(async () => {
68	  await new Promise((r) => setTimeout(r, 50));
69	  const { pres, theme } = captured;
70	  fs.mkdirSync(outDir, { recursive: true });
71	  if (range === "notes") return writeNotes(pres, JSON.parse(fs.readFileSync(rest[0], "utf8")));
72	  const [a, b] = range.split("-").map(Number);
73	  const reqs = [];
74	  const master = opt("--master");
75	  if (master) reqs.push(colorSchemeRequest(master, theme));
76	  for (let n = a; n <= b; n++) reqs.push(...slideRequests(pres.slides[n - 1], n, theme, flag("--rgb")));
77	  const del = opt("--delete");
78	  if (del) reqs.push({ deleteObject: { objectId: del } });
79	  const file = path.join(outDir, `requests-${a}-${b}.json`);
80	  fs.writeFileSync(file, JSON.stringify(reqs));
81	  console.log(file, fs.statSync(file).size, "bytes", reqs.length, "requests");
82	});
83	
84	// ---- 変換 ----
85	const r3 = (v) => Math.round(v * 1000) / 1000;
86	const pt = (inch) => Math.round(inch * PT * 100) / 100;
87	function hexRgb(hex) {
88	  const n = parseInt(hex, 16);
89	  return { red: r3(((n >> 16) & 255) / 255), green: r3(((n >> 8) & 255) / 255), blue: r3((n & 255) / 255) };
90	}
91	function color(c, theme, rgb) {
92	  if (c.startsWith("@")) {
93	    const k = c.slice(1);
94	    return rgb ? { rgbColor: hexRgb(theme.colors[THEME_KEYS[k]]) } : { themeColor: k };
95	  }
96	  return { rgbColor: hexRgb(c) };
97	}
98	function colorSchemeRequest(masterId, theme) {
99	  const colors = Object.entries(THEME_KEYS).map(([type, k]) => ({ type, color: hexRgb(theme.colors[k]) }));
100	  return { updatePageProperties: { objectId: masterId, pageProperties: { colorScheme: { colors } }, fields: "colorScheme.colors" } };
101	}
102	function geom(page, x, y, w, h) {
103	  return {
104	    pageObjectId: page,
105	    size: { width: { magnitude: pt(w), unit: "PT" }, height: { magnitude: pt(h), unit: "PT" } },
106	    transform: { scaleX: 1, scaleY: 1, translateX: pt(x), translateY: pt(y), unit: "PT" },
107	  };
108	}
109	const ALIGN = { left: "START", center: "CENTER", right: "END" };
110	const VALIGN = { top: "TOP", middle: "MIDDLE", bottom: "BOTTOM" };
111	const DASH = { dash: "DASH", sysDot: "DOT", sysDash: "DASH" };
112	
113	function slideRequests(slide, n, theme, rgb) {
114	  const page = `sl_${String(n).padStart(2, "0")}`;
115	  // スライド番号は作らない。API ではレイアウトのスライド番号のプレースホルダーをスライドに作れないため、
116	  // Google スライドのメニューの「挿入 > スライド番号」で付ける
117	  const reqs = [{ createSlide: { objectId: page, insertionIndex: n - 1, slideLayoutReference: { predefinedLayout: "BLANK" } } }];
118	  const bg = slide.master.background && slide.master.background.color;
119	  if (bg && bg !== "FFFFFF") {
120	    reqs.push({ updatePageProperties: { objectId: page, pageProperties: { pageBackgroundFill: { solidFill: { color: color(bg, theme, rgb) } } }, fields: "pageBackgroundFill.solidFill.color" } });
121	  }
122	  let k = 0;
123	  const id = () => `e${String(n).padStart(2, "0")}_${String(++k).padStart(2, "0")}`;
124	  const col = (c) => color(c, theme, rgb);
125	
126	  for (const it of slide.items) {
127	    let o = it.o;
128	    if (it.kind === "text" && o.placeholder) {
129	      const ph = slide.master.objects.find((x) => x.placeholder.options.name === o.placeholder).placeholder.options;
130	      o = Object.assign({}, ph, { isTextBox: true });
131	    }
132	    if (it.kind === "shape" && it.type === SHAPES.LINE) { reqs.push(...lineRequests(id(), page, o, col)); continue; }
133	    if (it.kind === "text" && OVERLAY.has(o.shape)) {
134	      // Google スライドは円・円柱・山形の中の文字を、図形の内側の狭い四角に収めるので、
135	      // 図形と文字を分け、図形の外形に合わせた文字の箱を上に重ねる
136	      slide.items.splice(slide.items.indexOf(it) + 1, 0,
137	        { kind: "text", t: it.t, o: Object.assign({}, o, { shape: undefined, overlay: true }) });
138	      it.kind = "shape"; it.type = o.shape;
139	    }
140	    const oid = id();
141	    const isBox = it.kind === "text" && !o.shape;
142	    let { x, y, w, h } = o;
143	    const margin = o.margin === undefined ? (isBox && !o.overlay ? 0 : 6) : o.margin;
144	    if (isBox && o.overlay) {
145	      const [mt, mr, mb, ml] = (Array.isArray(margin) ? margin : [margin, margin, margin, margin]).map((m) => m / PT);
146	      x += ml; y += mt; w -= ml + mr; h -= mt + mb;
147	    }
148	    if (isBox && (o.overlay || margin === 0)) { x -= PAD_X; y -= PAD_Y; w += 2 * PAD_X; h += 2 * PAD_Y; }
149	    let shapeType = isBox ? "TEXT_BOX" : (it.kind === "shape" ? it.type : o.shape);
150	    // Google スライドでは角の丸みを変えられないので、大きな箱は角の丸い四角にしない
151	    if (shapeType === "ROUND_RECTANGLE" && Math.min(w, h) > 1.0) shapeType = "RECTANGLE";
152	    reqs.push({ createShape: { objectId: oid, shapeType, elementProperties: geom(page, x, y, w, h) } });
153	
154	    const sp = {}, fields = [];
155	    if (!isBox) {
156	      const f = o.fill || {};
157	      sp.shapeBackgroundFill = { solidFill: { color: col(f.color || SCHEME.background1) } };
158	      if (f.transparency) sp.shapeBackgroundFill.solidFill.alpha = r3(1 - f.transparency / 100);
159	      fields.push("shapeBackgroundFill");
160	      if (o.line && o.line.color) {
161	        sp.outline = { outlineFill: { solidFill: { color: col(o.line.color) } }, weight: { magnitude: o.line.width || 1, unit: "PT" } };
162	        if (o.line.dashType) sp.outline.dashStyle = DASH[o.line.dashType];
163	      } else sp.outline = { propertyState: "NOT_RENDERED" };
164	      fields.push("outline");
165	    }
166	    const va = VALIGN[o.valign || (isBox && !o.overlay ? "top" : "middle")];
167	    // 文字の無い図形には、縦の位置を指定しない（要求を短くするため）
168	    if (it.kind === "text" && (!isBox || va !== "TOP")) { sp.contentAlignment = va; fields.push("contentAlignment"); }
169	    if (fields.length) reqs.push({ updateShapeProperties: { objectId: oid, shapeProperties: sp, fields: fields.join(",") } });
170	
171	    if (it.kind === "text") reqs.push(...textRequests(oid, it.t, o, isBox, col));
172	  }
173	  return reqs;
174	}
175	
176	function lineRequests(oid, page, o, col) {
177	  const { x, y, w, h } = o;
178	  const e = geom(page, x, y, w, h);
179	  // 右から左・下から上の線は、拡大率を負にして向きを反転する
180	  if (o.flipH) { e.transform.scaleX = -1; e.transform.translateX = pt(x + w); }
181	  if (o.flipV) { e.transform.scaleY = -1; e.transform.translateY = pt(y + h); }
182	  const l = o.line;
183	  const lp = { lineFill: { solidFill: { color: col(l.color) } }, weight: { magnitude: l.width || 1, unit: "PT" },
184	    dashStyle: l.dashType ? DASH[l.dashType] : "SOLID",
185	    endArrow: l.endArrowType ? "FILL_ARROW" : "NONE", startArrow: l.beginArrowType ? "FILL_ARROW" : "NONE" };
186	  return [
187	    { createLine: { objectId: oid, category: "STRAIGHT", elementProperties: e } },
188	    { updateLineProperties: { objectId: oid, lineProperties: lp, fields: "lineFill,weight,dashStyle,endArrow,startArrow" } },
189	  ];
190	}
191	
192	function textRequests(oid, t, o, isBox, col) {
193	  const runs = typeof t === "string" ? [{ text: t, options: {} }] : t;
194	  let full = "";
195	  const spans = [];
196	  runs.forEach((r) => {
197	    const ro = Object.assign({}, r.options);
198	    const start = full.length;
199	    full += r.text + (ro.breakLine ? "\n" : "");
200	    // 改行も同じ範囲に含める。含めないと改行の文字が既定の大きさのまま残り、その行が高くなる
201	    spans.push({ start, end: full.length, o: ro });
202	  });
203	  if (!full) return [];
204	  const reqs = [{ insertText: { objectId: oid, text: full } }];
205	  const styleOf = (ro) => {
206	    const s = { fontFamily: FONT, fontSize: { magnitude: ro.fontSize || o.fontSize || 18, unit: "PT" } };
207	    // 新しい箱の文字は太字ではないので、太字のときだけ指定する（要求を短くするため）
208	    if (ro.bold !== undefined ? ro.bold : o.bold) s.bold = true;
209	    s.foregroundColor = { opaqueColor: col(ro.color || o.color || SCHEME.text1) };
210	    if (ro.hyperlink) s.link = { url: ro.hyperlink.url };
211	    return s;
212	  };
213	  const styles = spans.map((sp) => styleOf(sp.o));
214	  const same = styles.every((s) => JSON.stringify(s) === JSON.stringify(styles[0]));
215	  const fieldsOf = (s) => "fontFamily,fontSize" + (s.bold ? ",bold" : "") + ",foregroundColor" + (s.link ? ",link" : "");
216	  if (same) {
217	    reqs.push({ updateTextStyle: { objectId: oid, textRange: { type: "ALL" }, style: styles[0], fields: fieldsOf(styles[0]) } });
218	  } else {
219	    spans.forEach((sp, i) => {
220	      if (sp.end === sp.start) return;
221	      reqs.push({ updateTextStyle: { objectId: oid, textRange: { type: "FIXED_RANGE", startIndex: sp.start, endIndex: sp.end }, style: styles[i], fields: fieldsOf(styles[i]) } });
222	    });
223	  }
224	  const ps = {}, pf = [];
225	  const al = ALIGN[o.align || (isBox && !o.overlay ? "left" : "center")];
226	  if (!isBox || al !== "START") { ps.alignment = al; pf.push("alignment"); }
227	  if (o.paraSpaceAfter) { ps.spaceBelow = { magnitude: o.paraSpaceAfter, unit: "PT" }; pf.push("spaceBelow"); }
228	  if (pf.length) reqs.push({ updateParagraphStyle: { objectId: oid, textRange: { type: "ALL" }, style: ps, fields: pf.join(",") } });
229	  if (spans.some((sp) => sp.o.bullet)) {
230	    reqs.push({ createParagraphBullets: { objectId: oid, textRange: { type: "ALL" }, bulletPreset: "BULLET_DISC_CIRCLE_SQUARE" } });
231	    // 字下げのデフォルト値は大きく、狭い箱では行が折り返されるので、記号の幅だけにする
232	    reqs.push({ updateParagraphStyle: { objectId: oid, textRange: { type: "ALL" },
233	      style: { indentFirstLine: { magnitude: 0, unit: "PT" }, indentStart: { magnitude: BULLET_INDENT, unit: "PT" } },
234	      fields: "indentFirstLine,indentStart" } });
235	  }
236	  return reqs;
237	}
238	
239	function writeNotes(pres, ids) {
240	  // ids: { "sl_01": "<speakerNotesObjectId>", ... }
241	  const reqs = [];
242	  pres.slides.forEach((s, i) => {
243	    const page = `sl_${String(i + 1).padStart(2, "0")}`;
244	    if (s.notes && ids[page]) reqs.push({ insertText: { objectId: ids[page], text: s.notes } });
245	  });
246	  const file = path.join(outDir, "requests-notes.json");
247	  fs.writeFileSync(file, JSON.stringify(reqs));
248	  console.log(file, fs.statSync(file).size, "bytes", reqs.length, "requests");
249	}
250

1	// 無停止リリースの説明資料を作る。
2	// 実行: NODE_PATH=<deckbuild>/node_modules node build.js <出力ファイル>
3	const path = require("path");
4	const pptxgen = require("pptxgenjs");
5	const SKILL = process.env.PPTX_SKILL_DIR;
6	const { applyTheme } = require(path.join(SKILL, "scripts/apply_theme.js"));
7	
8	const OUT = process.argv[2] || "zero-downtime.pptx";
9	
10	const THEME = {
11	  name: "ZeroDowntime",
12	  headFontFace: "Noto Sans JP",
13	  bodyFontFace: "Noto Sans JP",
14	  colors: {
15	    dk1: "1F2933", lt1: "FFFFFF", dk2: "52606D", lt2: "F2F4F7",
16	    accent1: "0F8B8D", // 新しい版
17	    accent2: "7B8794", // 古い版
18	    accent3: "D9480F", // 失敗・壊す
19	    accent4: "2F9E44", // 安全・成功
20	    accent5: "F0A202", // 新旧が重なる期間
21	    accent6: "1C3D5A", // DB と migration
22	    hlink: "0F6E8C", folHlink: "6B4F9E",
23	  },
24	};
25	
26	const pres = new pptxgen();
27	pres.layout = "LAYOUT_16x9"; // 10 x 5.625 インチ
28	pres.title = "無停止リリースと、アプリケーションの作り方";
29	pres.theme = { headFontFace: THEME.headFontFace, bodyFontFace: THEME.bodyFontFace };
30	const C = pres.SchemeColor;
31	const NEW = C.accent1, OLD = C.accent2, BAD = C.accent3, OK = C.accent4,
32	  OVERLAP = C.accent5, DB = C.accent6, TEXT = C.text1, MUTED = C.text2,
33	  PANEL = C.background2, WHITE = C.background1;
34	const S = pres.shapes;
35	
36	// ---- レイアウト ----
37	pres.defineSlideMaster({
38	  title: "TITLE",
39	  background: { color: "1C3D5A" },
40	  objects: [
41	    { placeholder: { options: { name: "title", type: "title", x: 0.6, y: 1.35, w: 8.8, h: 1.1,
42	      fontSize: 32, bold: true, color: WHITE, valign: "bottom", margin: 0 }, text: "" } },
43	    { placeholder: { options: { name: "sub", type: "body", x: 0.6, y: 2.55, w: 8.8, h: 0.5,
44	      fontSize: 16, color: WHITE, valign: "top", margin: 0 }, text: "" } },
45	  ],
46	});
47	pres.defineSlideMaster({
48	  title: "CONTENT",
49	  background: { color: "FFFFFF" },
50	  objects: [
51	    { placeholder: { options: { name: "kicker", type: "body", x: 0.5, y: 0.28, w: 9, h: 0.3,
52	      fontSize: 12, bold: true, color: NEW, valign: "middle", margin: 0 }, text: "" } },
53	    { placeholder: { options: { name: "title", type: "title", x: 0.5, y: 0.58, w: 9, h: 0.62,
54	      fontSize: 24, bold: true, color: TEXT, valign: "middle", margin: 0 }, text: "" } },
55	  ],
56	  slideNumber: { x: 9.1, y: 5.2, w: 0.5, h: 0.3, fontSize: 10, color: MUTED, align: "right" },
57	});
58	
59	// ---- 描画の部品 ----
60	function box(s, x, y, w, h, t, o = {}) {
61	  const shape = o.shape || S.ROUNDED_RECTANGLE;
62	  const opt = {
63	    shape, x, y, w, h,
64	    fill: { color: o.fill || WHITE, transparency: o.tr || 0 },
65	    color: o.color || TEXT, fontSize: o.fontSize || 14, bold: !!o.bold,
66	    align: o.align || "center", valign: o.valign || "middle",
67	    margin: o.margin === undefined ? 6 : o.margin, // ポイント
68	    objectName: o.name,
69	  };
70	  if (shape === S.ROUNDED_RECTANGLE) opt.rectRadius = o.radius === undefined ? 0.08 : o.radius;
71	  if (o.line) opt.line = { color: o.line, width: o.lineW || 1, dashType: o.dash };
72	  s.addText(t, opt);
73	}
74	function text(s, t, x, y, w, h, o = {}) {
75	  s.addText(t, {
76	    x, y, w, h, isTextBox: true, fontSize: o.fontSize || 14, color: o.color || TEXT,
77	    bold: !!o.bold, align: o.align || "left", valign: o.valign || "top",
78	    margin: o.margin === undefined ? 0 : o.margin, objectName: o.name,
79	    paraSpaceAfter: o.psa,
80	  });
81	}
82	function arrow(s, x1, y1, x2, y2, o = {}) {
83	  s.addShape(S.LINE, {
84	    x: Math.min(x1, x2), y: Math.min(y1, y2), w: Math.abs(x2 - x1), h: Math.abs(y2 - y1),
85	    flipH: x2 < x1, flipV: y2 < y1,
86	    line: { color: o.color || MUTED, width: o.width || 1.5, dashType: o.dash,
87	      endArrowType: o.noHead ? undefined : "triangle", beginArrowType: o.both ? "triangle" : undefined },
88	  });
89	}
90	function badge(s, n, x, y, d, o = {}) {
91	  s.addText(String(n), { shape: S.OVAL, x, y, w: d, h: d, fill: { color: o.fill || NEW },
92	    color: WHITE, fontSize: o.fontSize || 12, bold: true, align: "center", valign: "middle", margin: 0 });
93	}
94	function takeaway(s, t) {
95	  text(s, t, 0.5, 4.78, 8.5, 0.42, { fontSize: 14, bold: true, color: TEXT, valign: "middle", name: "takeaway" });
96	}
97	function content(section, kicker, title) {
98	  const s = pres.addSlide({ masterName: "CONTENT", sectionTitle: section });
99	  s.addText(kicker, { placeholder: "kicker" });
100	  s.addText(title, { placeholder: "title" });
101	  return s;
102	}
103	function bullets(items, o = {}) {
104	  return items.map((t, i) => ({ text: t, options: { bullet: true, breakLine: i < items.length - 1,
105	    fontSize: o.fontSize || 14, color: o.color || TEXT } }));
106	}
107	function card(s, x, y, w, h, o = {}) {
108	  s.addShape(S.ROUNDED_RECTANGLE, { x, y, w, h, rectRadius: 0.1,
109	    fill: { color: o.fill || PANEL, transparency: o.tr || 0 }, objectName: o.name });
110	}
111	
112	// ======== 表紙 ========
113	pres.addSection({ title: "表紙" });
114	{
